survey.custom_css:
.edsl-survey-container { background: #fbf7f0; font-family: Georgia, 'Times New Roman', serif }
.edsl-question-text { color: #7c2d12; font-size: 1.35rem; letter-spacing: -0.01em }
.edsl-option { border: 1px solid #e7d9c4; border-radius: 0.5rem; padding: 0.5rem 0.75rem; background: #fffdf9 }
.edsl-option:hover { border-color: #c2410c }
.edsl-radio { accent-color: #c2410c }
.edsl-progress-fill { background: #c2410c }
.edsl-comment-field { border-color: #e7d9c4; background: #fffdf9 }
